void openSceneEditor(App& app){
    if(!app.loaded||!app.canWrite())throw std::runtime_error("请等待工程加载完成");if(auto current=active.lock()){ShowWindow(current->hwnd,SW_SHOW);return;}auto self=std::make_shared<SceneEditor>(app);active=self;self->init();EnableWindow(app.hwnd,FALSE);ShowWindow(self->hwnd,SW_SHOW);MSG msg{};while(!self->done&&GetMessageW(&msg,nullptr,0,0)>0){if(msg.message==WM_KEYDOWN&&msg.wParam==VK_ESCAPE){self->done=true;continue;}if(!IsDialogMessageW(self->hwnd,&msg)){TranslateMessage(&msg);DispatchMessageW(&msg);}}auto value=self->accepted?self->validated:J();bool stale=self->observed!=app.tokens();EnableWindow(app.hwnd,TRUE);KillTimer(self->hwnd,1);DestroyWindow(self->hwnd);self->hwnd=nullptr;active.reset();SetForegroundWindow(app.hwnd);if(!value.null()){if(stale)throw std::runtime_error("工程已变化，草稿未应用");auto observed=self->observed;app.userAction([&app,value,observed]{if(observed!=app.tokens())throw std::runtime_error("工程已变化，草稿未应用");app.mutate("scene_animation",J::object({{"settings",value}}));});}
}
J sceneEditorCommand(App& app,const J& request){
    auto operation=request["operation"].str("status");if(operation=="open"){PostMessageW(app.hwnd,WM_APP+71,0,0);return J::object({{"queued",true}});}auto self=active.lock();if(!self)return J::object({{"open",false}});
    if(operation=="capture"){self->capture(fs::path(wide(request["path"].str())),request["overwrite"].boolean());return J::object({{"path",request["path"]},{"purpose","discussion capture of own editor"}});}if(operation=="cancel")self->done=true;else if(operation=="apply")self->apply();else if(operation=="invoke"){auto name=request["name"].str();if(!self->actions.count(name))throw std::runtime_error("Unknown editor action");self->actions[name]();}else if(operation=="field"){
        auto id=request["name"].str();if(!self->fields.count(id))throw std::runtime_error("Unknown editor field");HWND h=self->fields[id];if(Form::className(h)==L"Edit")setText(h,request["value"].isString()?request["value"].str():request["value"].dump());else if(Form::className(h)==L"ComboBox"){int wanted=request["value"].integer(-1);if(wanted<0||wanted>=SendMessageW(h,CB_GETCOUNT,0,0))throw std::runtime_error("Editor selection out of range");comboSet(h,wanted);SendMessageW(GetParent(h),WM_COMMAND,MAKEWPARAM(GetDlgCtrlID(h),CBN_SELCHANGE),LPARAM(h));}else throw std::runtime_error("Editor field is read only");
    }else if(operation!="status")throw std::runtime_error("Unknown editor operation");return self->status();
}
